import recordedUsage from './claude-usage-recorded.json';
import {describe,it,expect} from 'vitest';
import {ClaudeEvents,permissionResult,nativeOptions} from './claude-events.mjs';
import transcript from './claude-recorded.json';
import denied from './claude-denied-recorded.json';
import resumed from './claude-resume-recorded.json';
describe('Claude SDK recorded transcript',()=>{
 it('streams the recorded resumed session without replaying old edits',()=>{const r=new ClaudeEvents('resume','/tmp');const events=resumed.flatMap(m=>r.apply(m));expect(events.filter(e=>e.method==='item/agentMessage/delta').map(e=>e.params.delta).join('')).toContain('hello.txt');expect(events.some(e=>e.method==='item/started')).toBe(false);expect(events.at(-1).params.turn.status).toBe('completed');});
 it('maps the T3 recorded denied write to failure without a success file event',()=>{const r=new ClaudeEvents('denied','/tmp');const edits=denied.flatMap(m=>r.apply(m)).filter(e=>e.method==='item/completed'&&e.params.item.type==='fileChange');expect(edits.length).toBeGreaterThan(0);expect(edits.every(e=>e.params.item.status==='failed')).toBe(true);});
 it('streams text, starts edits and completes successful file writes',()=>{const r=new ClaudeEvents('turn','/tmp');const events=transcript.flatMap(m=>r.apply(m));expect(events.some(e=>e.method==='item/agentMessage/delta')).toBe(true);expect(events.some(e=>e.method==='item/completed'&&e.params.item.type==='fileChange'&&e.params.item.status==='completed')).toBe(true);});
 it('classifies native interrupt as stopped',()=>{const r=new ClaudeEvents('turn','/tmp');expect(r.apply(transcript.find(m=>m.terminal_reason==='aborted_streaming')).at(-1).params.turn.status).toBe('interrupted');});
 it('approves unchanged input and rejects denied steps',()=>{const input={file_path:'/tmp/a'};expect(permissionResult({decision:'accept'},input)).toEqual({behavior:'allow',updatedInput:input});expect(permissionResult({decision:'decline'},input).behavior).toBe('deny');});
 it('retains reasoning only when the provider exposes it',()=>{const r=new ClaudeEvents('turn','/tmp');r.apply({type:'stream_event',event:{type:'content_block_start'}});expect(r.apply({type:'stream_event',event:{type:'content_block_delta',delta:{type:'thinking_delta',thinking:'Checking'}}})[0].params.delta).toBe('Checking');});
 it('reports errors without inventing a successful turn',()=>{expect(new ClaudeEvents('t','/tmp').apply({type:'result',is_error:true,errors:['offline']})[0].params.turn).toEqual({id:'t',status:'failed',error:{message:'offline'}});});
 it('does not turn denied edits into successful file events',()=>{const r=new ClaudeEvents('t','/tmp');r.apply({type:'assistant',message:{content:[{type:'tool_use',id:'a',name:'Write',input:{file_path:'/tmp/a'}}]}});expect(r.apply({type:'user',message:{content:[{type:'tool_result',tool_use_id:'a',is_error:true,content:'Denied'}]}})[0].params.item.status).toBe('failed');});
});

it('passes model and effort overrides while preserving the native resume id',()=>{const opts=nativeOptions({cwd:'/tmp',model:'native-model',effort:'medium',approvalPolicy:'untrusted'},'/installed/claude','original-session',()=>{});expect(opts.resume).toBe('original-session');expect(opts.model).toBe('native-model');expect(opts.effort).toBe('medium');expect(opts.settingSources).toEqual(['user','project','local']);expect(opts.permissionMode).toBe('default');});

it('emits native limit events and assistant limit failure codes',()=>{const r=new ClaudeEvents('t','/tmp');expect(r.apply({type:'rate_limit_event',rate_limit_info:{status:'rejected',resetsAt:2000000000,utilization:1}})).toEqual([{method:'native/limits',params:{status:'rejected',resetsAt:2000000000,utilization:1}}]);expect(r.apply({type:'assistant',error:'rate_limit',message:{content:[]}})[0].params.code).toBe('usage_limit_reached');});
it('records the final native usage once without counting partial assistant blocks',()=>{const r=new ClaudeEvents('t','/tmp');const result={type:'result',usage:recordedUsage};expect(r.apply(result).filter(e=>e.method==='native/usage')[0].params.input_tokens).toBe(result.usage.input_tokens);});
it('subtracts resumed model totals including helper calls',()=>{const r=new ClaudeEvents('t','/tmp');r.usageBaseline={model:{inputTokens:100,outputTokens:5,cacheReadInputTokens:80,cacheCreationInputTokens:10}};const events=r.apply({type:'result',modelUsage:{model:{inputTokens:130,outputTokens:12,cacheReadInputTokens:100,cacheCreationInputTokens:10},helper:{inputTokens:2,outputTokens:1}}});expect(events.find(e=>e.method==='native/usage').params).toEqual({input_tokens:32,output_tokens:8,cache_read_input_tokens:20,cache_creation_input_tokens:0,scope:'all'});});
it('falls back to explicitly per-turn figures for a legacy resumed session',()=>{const r=new ClaudeEvents('t','/tmp');r.usageBaseline=null;const events=r.apply({type:'result',usage:recordedUsage,modelUsage:{model:{inputTokens:999999}}});expect(events.find(e=>e.method==='native/usage').params.input_tokens).toBe(recordedUsage.input_tokens);expect(events.find(e=>e.method==='native/usage').params.scope).toBe('main');expect(events.find(e=>e.method==='native/modelUsage').params.model.inputTokens).toBe(999999);});
it('handles native counter resets without negative usage',()=>{const r=new ClaudeEvents('t','/tmp');r.usageBaseline={model:{inputTokens:500,outputTokens:40}};const events=r.apply({type:'result',modelUsage:{model:{inputTokens:10,outputTokens:3}}});expect(events.find(e=>e.method==='native/usage').params.input_tokens).toBe(10);});
it('does not replace a saved baseline with empty crash counters',()=>{const r=new ClaudeEvents('t','/tmp');r.usageBaseline={model:{inputTokens:500}};const events=r.apply({type:'result',modelUsage:{},usage:recordedUsage});expect(events.some(e=>e.method==='native/modelUsage')).toBe(false);expect(events.find(e=>e.method==='native/usage').params.input_tokens).toBe(recordedUsage.input_tokens);});

import missing from './claude-missing.json';
import {missingSessionError} from './claude-events.mjs';
it('recognizes the recorded missing session without classifying other failures',()=>{expect(missing.subtype).toBe('error_during_execution');expect(missing.errors.some(missingSessionError)).toBe(true);for(const error of ['Authentication failed','Usage limit reached','Connection reset','Permission denied'])expect(missingSessionError(error)).toBe(false);});
